//! A category groups request messages so they all travel over a single request / response
//! channel, wrapped in the category's request and response enums. Categories are generated by
//! `define_request_message_category`, the requester and responder here are shared by all of them

use crate::feagi_message::feagi_message_path::configurables::FeagiMessagePathConfigurables;
use crate::feagi_message::request::feagi_request_descriptor::{FeagiMessageEnum, FeagiRequestMessageDescriptor};
use crate::feagi_message::request::feagi_request_message::FeagiRequestMessage;
use crate::parallelism::feagi_channel::channel_error::{FeagiChannelReceiveError, FeagiRequestError};
use crate::parallelism::feagi_channel::recycling::Recyclable;
use crate::parallelism::feagi_channel::request_response_channel::channel_backend::FeagiRequestResponseChannelBackend;
use crate::parallelism::feagi_channel::request_response_channel::{FeagiRequester, FeagiResponder};
#[cfg(feature = "alloc")]
use crate::parallelism::feagi_channel::request_response_channel::implementations::dynamic::FeagiRequestResponseChannelsAllocBackend;

/// A zero sized struct that contains static information about a category of request messages
pub trait FeagiRequestCategory: Sized {
    const CATEGORY_NAME: &'static str;
    /// Details about this category. Used in doc generation
    const CATEGORY_DESCRIPTION: &'static str;
    /// Prepended to the path of every message of this category
    const BASE_PATH: &'static str;

    /// Has a variant holding each message of this category
    type RequestEnum: Recyclable;
    /// Has a variant holding the response (or error) of each message of this category.
    /// Serializes as just the response payload, or the error, it holds
    type ResponseEnum: Recyclable + serde::Serialize;

    /// Which message of this category a path is, with the path parameters parsed from it. The
    /// payload is not decoded yet
    type PathMatch;

    /// Finds the message of `method` whose path (base path included) is `segments`, the already
    /// decoded segments of a request path. Walks the category's paths as a tree, so the cost
    /// grows with the path's length rather than the number of messages
    fn match_message_path(configurables: &Self::Configurables, method: FeagiMessageEnum, segments: &[&str]) -> Option<Self::PathMatch>;

    /// Whether any message of this category, of any method, has the path `segments`. Tells a
    /// request of the wrong method apart from one for a path that doesn't exist
    fn message_path_exists(configurables: &Self::Configurables, segments: &[&str]) -> bool;

    /// Decodes the matched message's payload with `decoder`, and builds the request. `None`
    /// if the payload could not be decoded
    fn decode_request<Decoder: FeagiRequestPayloadDecoder>(path_match: Self::PathMatch, decoder: Decoder) -> Option<Self::RequestEnum>;

    /// Whether `response` is the error of a message, rather than its response payload
    fn response_is_error(response: &Self::ResponseEnum) -> bool;

    /// The response to `request` with its message's `FeagiMessageError::NOT_IMPLEMENTED` error.
    /// For responders that don't handle (some of) the category's messages yet, so those
    /// requests are still answered rather than left waiting
    fn not_implemented_response(request: &Self::RequestEnum) -> Self::ResponseEnum;
    /// The runtime set path segments shared by all messages of this category
    type Configurables: FeagiMessagePathConfigurables + 'static;
    /// `Some` for categories that declare no configurables, so their (empty) configurables
    /// don't have to be given
    const EMPTY_CONFIGURABLES: Option<&'static Self::Configurables>;
    /// Every message descriptor of this category, nested as `NMDes<Head, NMDes<..., NNull>>`
    type NestedMessageDescriptors;

    /// Create no-alloc compatible channels for compile time using default settings using the
    /// given backend for the entire category, using the request/response enums as their data types,
    fn spawn_requester_responser_pair<ChannelBackend: FeagiRequestResponseChannelBackend, const QUEUE_SIZE: usize>()
        -> (FeagiCategoryRequester<Self, ChannelBackend>,
            FeagiCategoryResponder<Self, ChannelBackend>) {
        let (requester, responder) = ChannelBackend::create_default_channel_pair::<Self::RequestEnum, Self::ResponseEnum, QUEUE_SIZE>();
        (FeagiCategoryRequester::new(requester), FeagiCategoryResponder::new(responder))
    }

    /// Create at runtime alloc utilizing channels for the entire category, using the
    /// request/response enums as their data types
    #[cfg(feature = "alloc")]
    fn spawn_alloc_requester_responser_pair(queue_capacity: usize)
        -> (FeagiCategoryRequester<Self, FeagiRequestResponseChannelsAllocBackend>,
            FeagiCategoryResponder<Self, FeagiRequestResponseChannelsAllocBackend>) {
        let (requester, responder) = FeagiRequestResponseChannelsAllocBackend::create_channels(queue_capacity);
        (FeagiCategoryRequester::new(requester), FeagiCategoryResponder::new(responder))
    }


    // This struct should be zero sized, no fields!

}

/// Where a request's payload comes from (a URL query, a json body, a zenoh payload, ...).
/// Decodes it into whichever payload type the matched message takes
pub trait FeagiRequestPayloadDecoder {
    /// `None` if the payload is not a valid `Payload`
    fn decode_payload<Payload: serde::de::DeserializeOwned>(self) -> Option<Payload>;
}

/// Response to a message `Message`, or the error that message responded with
pub type FeagiMessageResult<Message> = Result<
    <<Message as FeagiRequestMessage>::Descriptor as FeagiRequestMessageDescriptor>::ResponsePayload,
    <<Message as FeagiRequestMessage>::Descriptor as FeagiRequestMessageDescriptor>::ResponseError,
>;

//region Requester

/// Makes requests to whichever responder serves `Category`. Clone it to make requests from
/// several places to the same responder
pub struct FeagiCategoryRequester<Category, ChannelBackend>
where
    Category: FeagiRequestCategory,
    ChannelBackend: FeagiRequestResponseChannelBackend,
{
    requester: FeagiRequester<Category::RequestEnum, Category::ResponseEnum, ChannelBackend>,
}

impl<Category, ChannelBackend> FeagiCategoryRequester<Category, ChannelBackend>
where
    Category: FeagiRequestCategory,
    ChannelBackend: FeagiRequestResponseChannelBackend,
{
    /// Wraps the requester half of a channel pair carrying `Category`'s enums
    pub fn new(requester: FeagiRequester<Category::RequestEnum, Category::ResponseEnum, ChannelBackend>) -> Self {
        FeagiCategoryRequester { requester }
    }

    /// Sends `message` and waits for its response
    ///
    /// The outer error is of the channel (responder gone, channel closed, or it replied to a
    /// different message). The inner result is what the responder answered, including the
    /// message's own error
    pub async fn request<Message>(&mut self, message: Message) -> Result<FeagiMessageResult<Message>, FeagiRequestError>
    where
        Message: FeagiRequestMessage,
        Message::Descriptor: FeagiRequestMessageDescriptor<Category = Category>,
    {
        let response = self.requester.make_request(Message::Descriptor::into_category_request(message)).await?;
        Message::Descriptor::try_from_category_response(response).map_err(|_| FeagiRequestError::UnexpectedResponse)
    }

    /// Sends a request already wrapped in the category's request enum, and waits for the
    /// response enum
    pub async fn make_request(&mut self, request: Category::RequestEnum) -> Result<Category::ResponseEnum, FeagiRequestError> {
        self.requester.make_request(request).await
    }
}

impl<Category, ChannelBackend> Clone for FeagiCategoryRequester<Category, ChannelBackend>
where
    Category: FeagiRequestCategory,
    ChannelBackend: FeagiRequestResponseChannelBackend,
    FeagiRequester<Category::RequestEnum, Category::ResponseEnum, ChannelBackend>: Clone,
{
    fn clone(&self) -> Self {
        FeagiCategoryRequester {
            requester: self.requester.clone(),
        }
    }
}

//endregion

//region Responder

/// Answers the requests of `Category`, from any number of `FeagiCategoryRequester`s. Lives within
/// the worker that serves the category
// NOTE: Do NOT allow this to be clonable! There is exactly one responder per request channel
pub struct FeagiCategoryResponder<Category, ChannelBackend>
where
    Category: FeagiRequestCategory,
    ChannelBackend: FeagiRequestResponseChannelBackend,
{
    responder: FeagiResponder<Category::RequestEnum, Category::ResponseEnum, ChannelBackend>,
}

impl<Category, ChannelBackend> FeagiCategoryResponder<Category, ChannelBackend>
where
    Category: FeagiRequestCategory,
    ChannelBackend: FeagiRequestResponseChannelBackend,
{
    /// Wraps the responder half of a channel pair carrying `Category`'s enums
    pub fn new(responder: FeagiResponder<Category::RequestEnum, Category::ResponseEnum, ChannelBackend>) -> Self {
        FeagiCategoryResponder { responder }
    }

    /// Waits for the next request, then answers it with `processor`. A response is built with
    /// the message descriptor's `into_category_response`, or the response enum variant directly
    pub async fn async_process_next<Processor>(&self, processor: Processor) -> Result<(), FeagiChannelReceiveError>
    where
        Processor: AsyncFnOnce(Category::RequestEnum) -> Category::ResponseEnum,
    {
        self.responder.async_process_next(processor).await
    }

    /// Answers the next request with `processor` if one is queued, otherwise returns
    /// `ChannelEmpty` immediately
    pub async fn try_process_next<Processor>(&self, processor: Processor) -> Result<(), FeagiChannelReceiveError>
    where
        Processor: AsyncFnOnce(Category::RequestEnum) -> Category::ResponseEnum,
    {
        self.responder.try_process_next(processor).await
    }
}

//endregion
